import{_ as o,l as s,o as e,c as l,v as t,p as n,x as r,d,i as p,S as h}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"IDS / IPS","description":"","frontmatter":{"title":"IDS / IPS","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/ids-ips.md","filePath":"cs/ids-ips.md","lastUpdated":1789023840000}'),S={name:"cs/ids-ips.md"};function c(E,a,_,I,u,A){const i=s("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="ids-ips" tabindex="-1">IDS / IPS <a class="header-anchor" href="#ids-ips" aria-label="Permalink to &quot;IDS / IPS&quot;">​</a></h1><div class="epigraph"><p>入侵检测看流量或主机事件是否像已知滥用；防护系统还加上阻断。它们识别的是模式与异常，不是应用不变量。漏报与误报同时存在，所以要和日志、响应流程一起设计。</p><footer>—— 据 Roesch, Snort；Paxson, Bro；对照 NIST SP 800-94</footer></div><h2 id="定位" tabindex="-1">定位 <a class="header-anchor" href="#定位" aria-label="Permalink to &quot;定位&quot;">​</a></h2><p>上一课<a href="/cs/api-security-bola">BOLA</a>在应用授权。缺口是<strong>网络层可见性</strong>：应用仍会漏，流量侧能否看见扫描、已知利用特征、C2 形态。本课分工 IDS 与 IPS，不写逃避检测的步骤。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>防火墙课管策略放行。<a href="/cs/firewall-state">防火墙</a>不深检载荷。IDS：旁路告警；IPS：串接阻断。缺口是部署点（网络、主机）与加密流量的盲区。</p><h3 id="加密后载荷" tabindex="-1">加密后载荷 <a class="header-anchor" href="#加密后载荷" aria-label="Permalink to &quot;加密后载荷&quot;">​</a></h3><p>TLS 后 IDS 只见五元组与 SNI 一类元数据，除非终止 TLS——那是另一威胁模型。</p><p><span class="marginnote">SP 800-94。Snort/Bro 历史。禁止编写逃避 IDS 的教程。下一课规则语言。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对照误报成本（可用性）与漏报成本。主机 IDS 看系统调用。下一课 Snort/Suricata 规则形态。</p>',12)),(e(),n(h,null,{default:r(()=>[p(i,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20TAP%5B%22%E6%B5%81%E9%87%8F%E5%A4%8D%E5%88%B6%22%5D%20--%3E%20IDS%5B%22%E6%A3%80%E6%B5%8B%E5%91%8A%E8%AD%A6%22%5D%0A%20%20INLINE%5B%22%E4%B8%B2%E6%8E%A5%22%5D%20--%3E%20IPS%5B%22%E6%A3%80%E6%B5%8B%E5%B9%B6%E9%98%BB%E6%96%AD%22%5D%0A%20%20TLS%5B%22%E5%8A%A0%E5%AF%86%22%5D%20--%3E%20META%5B%22%E5%85%83%E6%95%B0%E6%8D%AE%E5%8F%AF%E8%A7%81%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>图中节点是本课的机制骨架；课程不把图展开成可运行的攻击步骤。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>检测服务完整与可用的观测。它不修复 BOLA。规则下一课把「像什么」写成可维护的签名。</p><p>前提写进合同之后，游戏外的误用只当失败模式点名，不在本课写成操作程序。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不写逃避。下一课规则。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>应用授权之后，流量侧仍要观测。</li><li>IDS 告警，IPS 阻断；加密后见元数据。</li><li>误报与漏报是合同，不是调参能消掉。</li><li>下一课 IDS 规则。</li><li>出处：Roesch, Snort；Paxson, Bro；NIST SP 800-94。</li></ul>',8))])}const m=o(S,[["render",c]]);export{B as __pageData,m as default};
